{
  "description": "The creature is a large quadrupedal animal shown in right-facing profile standing on a small patch of dry, sparsely grassed ground. Its hindquarters, torso, forequarters and limbs are those of a large tawny-brown felid with muscular legs and a long tail, while its head, neck, chest and back are covered in dense raptor-like plumage. The head has a hooked beak and a yellow eye, and two very large feathered wings are spread outward and upward from the upper back. The overall coloration is warm golden-brown and dark brown with cream patches on the neck and chest and a dark tuft at the tip of the tail.",
  "parts": [
    {
      "part": "head",
      "looks_like": "eagle-like with golden-brown feathers on the crown and cheeks, a sharp hooked beak that is yellow at the cere and dark gray at the tip, and a large yellow eye with a dark pupil facing right",
      "where": "at the front of the body on top of the feathered neck, facing right"
    },
    {
      "part": "legs",
      "looks_like": "four sturdy, muscular lion-like legs covered in short tawny fur that is lighter on the undersides and inner legs, with visible joints and musculature",
      "where": "two forelegs under the chest and two hind legs under the hips, supporting the body on the ground"
    },
    {
      "part": "feet",
      "looks_like": "four large paw-like feet with rounded toes, pale pads and short dark claws",
      "where": "at the ends of each leg in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a long slender lion-like tail covered in short tawny fur ending in a dark brown to black tuft of longer hair",
      "where": "extending from the rear of the hindquarters and hanging down behind the hind legs"
    },
    {
      "part": "wings",
      "looks_like": "two very large outspread wings with layered flight feathers in shades of golden-brown, medium brown and dark brown-gray with darker tips and paler undersides",
      "where": "attached to the upper back behind the neck, extending outward to the left and right and upward"
    },
    {
      "part": "feathers",
      "looks_like": "dense overlapping feathers in golden-brown, dark brown and cream, covering the head, neck and upper chest and forming the wings, with longer shaggy feathers hanging on the lower neck and chest",
      "where": "covering the head, the dorsal and lateral neck, the upper chest and the entire wings"
    },
    {
      "part": "mane",
      "looks_like": "a thick shaggy ruff of elongated brown and cream feathers/hair hanging down over the front of the chest and lower neck",
      "where": "around the neck and extending down the front of the chest between the forelegs"
    },
    {
      "part": "markings",
      "looks_like": "irregular cream-white patches interspersed among the darker brown feathers on the side of the neck and chest",
      "where": "on the lateral neck and upper chest"
    }
  ],
  "attached_objects": [],
  "animals": [
    "eagle",
    "lion"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 2,
  "extra_limb_pieces": 0,
  "tails": 1
}
